const data={projects:[['N','Northstar Studio','northstar.studio','WordPress','RU · EN','Подключен','148','8'],['C','Cedar Health','cedar.health','Custom API','EN','Подключен','62','5'],['V','Vela Academy','vela.academy','Не выбран','RO','Настройка','0','5']],integrations:[['OpenAI','Генерация, embeddings, изображения и speech.','Планируется',['text.generate','embeddings','image.generate','speech']],['WordPress','Публикация и обновление страниц через REST API.','Не подключено',['cms.discover','publish.create','publish.update']],['Google Search Console','Поисковые запросы, sitemap и индексирование.','Планируется',['search.analytics','sitemap.read','index.inspect']],['Custom Publishing API','Версионированный контракт для любой CMS.','Готов к подключению',['publish.create','publish.status','webhooks']],['TikTok','Видео: черновик или публикация после approval.','Требует проверки',['media.upload','social.post.create','status.read']],['Telegram Bot','Первый social-канал для текста, фото и видео.','Планируется',['social.post.create','media.upload']]]};
document.querySelector('#projectCards').innerHTML=data.projects.map(([l,n,url,cms,lang,status,pub,work])=>`<article class="card project"><div class="top"><b class="logo">${l}</b><span class="status ${status==='Настройка'?'muted':''}">${status}</span></div><h2>${n}</h2><p>${url}</p><div class="meta"><span>● ${cms}</span><span>${lang}</span></div><div class="stats"><span>Опубликовано<b>${pub}</b></span><span>В работе<b>${work}</b></span></div></article>`).join('');
document.querySelector('#integrationsCards').innerHTML=data.integrations.map(([n,d,s,c])=>`<article class="card integration"><div class="top"><b class="logo">${n.slice(0,2).toUpperCase()}</b><span class="status ${s!=='Готов к подключению'?'muted':''}">${s}</span></div><h2>${n}</h2><p>${d}</p><div class="caps">${c.map(x=>`<span>${x}</span>`).join('')}</div></article>`).join('');
const events={5:['Ревью: CMS','review'],6:['TikTok: 5 сигналов','video'],7:['LinkedIn: отчёт',''],10:['Статья: SEO-гайд',''],13:['Видео: контент-план','video'],18:['Ревью: интервью','review'],24:['Статья: AI-политика','']};let html='';for(let i=1;i<=35;i++){let date=i<=30?i:i-30,ev=events[date]&&i<=30?`<p class="event ${events[date][1]}">${events[date][0]}</p>`:'';html+=`<div class="day"><b>${date}</b>${ev}</div>`}document.querySelector('#days').innerHTML=html;
const names={overview:'Обзор',projects:'Проекты',calendar:'Календарь',quality:'Качество',integrations:'Интеграции',settings:'Настройки'};document.querySelectorAll('[data-view]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();let view=a.dataset.view;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===view));document.querySelectorAll('nav a').forEach(x=>x.classList.toggle('active',x===a));document.querySelector('#crumb').textContent=names[view];history.replaceState({},'',`#${view}`)}));
let dialog=document.querySelector('dialog');document.querySelectorAll('.new-project').forEach(x=>x.onclick=()=>dialog.showModal());document.querySelector('.x').onclick=()=>dialog.close();
